import{_ as e,C as r,o,c as d,a2 as t,E as n}from"./chunks/framework.BqNd1sPY.js";const _=JSON.parse('{"title":"D14：多模态、应用全景与总复习","description":"","frontmatter":{},"headers":[],"relativePath":"01-14天理论课/D14-多模态、应用全景与总复习.md","filePath":"01-14天理论课/D14-多模态、应用全景与总复习.md"}'),s={name:"01-14天理论课/D14-多模态、应用全景与总复习.md"};function l(m,a,k,c,h,w){const i=r("MermaidDiagram");return o(),d("div",null,[a[0]||(a[0]=t('<h1 id="d14-多模态、应用全景与总复习" tabindex="-1">D14：多模态、应用全景与总复习 <a class="header-anchor" href="#d14-多模态、应用全景与总复习" aria-label="Permalink to &quot;D14：多模态、应用全景与总复习&quot;">​</a></h1><h2 id="今日目标" tabindex="-1">今日目标 <a class="header-anchor" href="#今日目标" aria-label="Permalink to &quot;今日目标&quot;">​</a></h2><p>把 14 天知识连成一张图，了解多模态和应用边界，并为第三周训练项目做设计。</p><h2 id="多模态怎样接入" tabindex="-1">多模态怎样接入 <a class="header-anchor" href="#多模态怎样接入" aria-label="Permalink to &quot;多模态怎样接入&quot;">​</a></h2><p>视觉语言模型常把图像经过视觉编码器或视觉 <a href="/LLMTrain/05-速查表/术语速查#term-tokenizer" class="wiki-term" data-wiki-title="tokenizer" data-wiki-summary="负责把文本切成 token，并在 token 与整数 ID 之间转换的规则和词表。" data-wiki-misconception="tokenizer 是模型自己临时决定的切词方式。">tokenizer</a> 变成一串表示，再通过投影或连接模块交给语言模型处理。语音也可由专门编码器产生表示，或先转写为文本。</p><p>图像生成常使用扩散模型、自回归图像 <a href="/LLMTrain/05-速查表/术语速查#term-token" class="wiki-term" data-wiki-title="token" data-wiki-summary="文本经过分词规则得到的离散单元，随后会映射成整数 ID。" data-wiki-misconception="token 必然等于一个字或一个完整单词。">token</a> 模型或混合方法，不应把所有生成式 AI 都说成“逐字预测”。“世界模型”也没有唯一统一定义，使用该词时应说明它预测的状态、观测或行动是什么。</p><h2 id="应用不要按行业死记" tabindex="-1">应用不要按行业死记 <a class="header-anchor" href="#应用不要按行业死记" aria-label="Permalink to &quot;应用不要按行业死记&quot;">​</a></h2><p>把应用拆成五种模式更实用：</p><table tabindex="0"><thead><tr><th>模式</th><th>例子</th><th>核心风险</th></tr></thead><tbody><tr><td>生成</td><td>写作、代码、摘要</td><td>幻觉、版权、泄密</td></tr><tr><td>抽取与分类</td><td>合同字段、工单分类</td><td>漏检、偏差</td></tr><tr><td>检索问答</td><td>企业知识库</td><td>错检索、伪引用</td></tr><tr><td>工具代理</td><td>查询、下单、改配置</td><td>越权、不可逆操作</td></tr><tr><td>多模态理解/生成</td><td>看图问答、语音、图像生成</td><td>感知错误、深度伪造</td></tr></tbody></table><p>医疗、法律、金融等高风险领域还需要专业审查、权限、审计和当地法规合规，模型输出不能替代具备资质的判断。</p><h2 id="总知识地图" tabindex="-1">总知识地图 <a class="header-anchor" href="#总知识地图" aria-label="Permalink to &quot;总知识地图&quot;">​</a></h2>',11)),n(i,{code:""}),a[1]||(a[1]=t('<p>反馈不能自动倒回训练集。必须经过许可、脱敏、质量筛选、去重和评测隔离，否则数据飞轮会变成错误放大器。</p><h2 id="结业闭卷题" tabindex="-1">结业闭卷题 <a class="header-anchor" href="#结业闭卷题" aria-label="Permalink to &quot;结业闭卷题&quot;">​</a></h2><ol><li>从文本到下一个 <a href="/LLMTrain/05-速查表/术语速查#term-token" class="wiki-term" data-wiki-title="token" data-wiki-summary="文本经过分词规则得到的离散单元，随后会映射成整数 ID。" data-wiki-misconception="token 必然等于一个字或一个完整单词。">token</a> 写出至少六步。</li><li>为什么<a href="/LLMTrain/05-速查表/术语速查#term-causal-mask" class="wiki-term" data-wiki-title="causal mask" data-wiki-summary="在自回归训练中阻止当前位置读取未来 token 的遮罩。" data-wiki-misconception="它会阻止模型读取当前位置之前的内容。">因果遮罩</a>允许并行训练，却不能让生成一次完成？</li><li>train <a href="/LLMTrain/05-速查表/术语速查#term-loss" class="wiki-term" data-wiki-title="loss" data-wiki-summary="训练目标对应的误差标量，优化器尝试让它下降。" data-wiki-misconception="一个 loss 数值足以代表模型的全部质量。">loss</a> 下降而 val <a href="/LLMTrain/05-速查表/术语速查#term-loss" class="wiki-term" data-wiki-title="loss" data-wiki-summary="训练目标对应的误差标量，优化器尝试让它下降。" data-wiki-misconception="一个 loss 数值足以代表模型的全部质量。">loss</a> 上升意味着什么？</li><li><a href="/LLMTrain/05-速查表/术语速查#term-rag" class="wiki-term" data-wiki-title="RAG" data-wiki-summary="先检索外部资料，再把相关片段放进上下文辅助生成。" data-wiki-misconception="检索到资料就能保证资料和答案都真实。">RAG</a> 和 <a href="/LLMTrain/05-速查表/术语速查#term-lora" class="wiki-term" data-wiki-title="LoRA" data-wiki-summary="冻结大部分基础权重，用低秩矩阵学习权重增量的参数高效微调方法。" data-wiki-misconception="LoRA 会自动压缩推理模型或保证无损。">LoRA</a> 分别更适合改变什么？</li><li><a href="/LLMTrain/05-速查表/术语速查#term-qlora" class="wiki-term" data-wiki-title="QLoRA" data-wiki-summary="以低比特形式保存冻结的基础模型，同时训练 LoRA 适配器。" data-wiki-misconception="LoRA 适配器本身被简单量化成 4 bit。">QLoRA</a> 的 4-bit 针对什么，为什么总显存不是简单除以四？</li><li>为什么 Benchmark 高分不能单独证明生产可用？</li><li><a href="/LLMTrain/05-速查表/术语速查#term-agent" class="wiki-term" data-wiki-title="Agent" data-wiki-summary="让模型参与工具选择、读取结果和多步决策循环的应用结构。" data-wiki-misconception="Agent 可以脱离权限、预算和人工确认自主执行。">Agent</a> 执行支付前需要哪些保护？</li><li><a href="/LLMTrain/05-速查表/术语速查#term-parameter" class="wiki-term" data-wiki-title="parameter" data-wiki-summary="模型中由训练确定的数字；训练时只有未冻结的参数会被更新。" data-wiki-misconception="一个参数对应一条可直接读取的事实。">参数</a>量、数据量和能力为什么不是简单线性关系？</li></ol><h2 id="第三周项目设计" tabindex="-1">第三周项目设计 <a class="header-anchor" href="#第三周项目设计" aria-label="Permalink to &quot;第三周项目设计&quot;">​</a></h2><p>项目目标不是生成优美长文，而是亲手验证：</p><p><code>数据 -&gt; 字符 ID -&gt; 因果 Transformer -&gt; 交叉熵 -&gt; 梯度更新 -&gt; 验证 -&gt; 生成</code></p><p>先阅读 <a href="./../02-第3周实战/">第 3 周实战入口</a>，完成环境检查，再运行未训练基线。不要跳过第 18 天的单 <a href="/LLMTrain/05-速查表/术语速查#term-batch" class="wiki-term" data-wiki-title="batch" data-wiki-summary="一次前向与反向计算共同处理的一组样本。" data-wiki-misconception="一个 batch 必然等于一次优化器更新或整个数据集。">batch</a> <a href="/LLMTrain/05-速查表/术语速查#term-overfitting" class="wiki-term" data-wiki-title="overfitting" data-wiki-summary="模型继续改善训练数据表现，却不能同步改善未见数据表现的现象。" data-wiki-misconception="训练 loss 下降就一定没有过拟合。">过拟合</a>。</p>',7))])}const u=e(s,[["render",l]]);export{_ as __pageData,u as default};
